/**
 * The game is a presentation of the same compiled, typed curriculum.
 * No translated exercise strings live here: answers and distractors are
 * generated by the existing language adapters.
 */
import { event } from '../core/algebra.js';
import type { Clause, Expression, LanguageProfile, PricedThing } from '../core/model.js';
import { realizeEnglish } from '../languages/en.js';
import { linearize } from '../languages/index.js';
import { CONCEPTS, DESCRIPTION_QUALITIES, LOCATABLE_PLACES, OBJECT_QUESTION_PREDICATES, PREDICATES, PRESENCE_THINGS } from '../core/vocabulary.js';
import { generatePractice } from '../learning/practice.js';
import type { GeneratedExample, GeneratedGuide, GeneratedLesson } from '../learning/types.js';

export interface DrillQuestion {
  readonly id: string;
  readonly english: string;
  readonly target: string;
  readonly options: readonly string[];
  readonly optionMeanings: readonly string[];
  readonly contextHint: string | null;
  readonly patternHint: string | null;
  readonly example: GeneratedExample;
}

export function nextLevelIndex(guide: GeneratedGuide, completed: ReadonlySet<string>): number {
  const first = guide.lessons.findIndex((lesson) => !completed.has(lesson.id));
  return first === -1 ? guide.lessons.length - 1 : first;
}

/** Shared level selection so the visible drill and its answer checker can never diverge. */
export function playableLesson(guide: GeneratedGuide, completed: ReadonlySet<string>, requested: string | null): GeneratedLesson {
  const requestedIndex = guide.lessons.findIndex((lesson) => lesson.id === requested);
  const index = requestedIndex >= 0 && levelUnlocked(guide, completed, requestedIndex)
    ? requestedIndex : nextLevelIndex(guide, completed);
  const lesson = guide.lessons[index];
  if (!lesson) throw new Error('Guide has no playable level');
  return lesson;
}

export function levelUnlocked(guide: GeneratedGuide, completed: ReadonlySet<string>, index: number): boolean {
  return index >= 0 && index < guide.lessons.length && index <= nextLevelIndex(guide, completed);
}

export function meaningBlocks(example: GeneratedExample, code: LanguageProfile['code']): readonly string[] {
  if (example.source.kind === 'convention') return ['EVERYDAY EXPRESSION'];
  const expression: Expression = example.source.expression;
  if (expression.kind === 'link') return ['STATEMENT 1', expression.connection.toUpperCase(), 'STATEMENT 2'];
  if (expression.kind === 'sequence') return expression.steps.map((_, i) => 'STEP ' + (i + 1));
  if (expression.kind === 'where') return ['WHERE?', String(CONCEPTS[expression.place]).toUpperCase()];
  if (expression.kind === 'route') return ['HOW TO GET?', String(CONCEPTS[expression.place]).toUpperCase()];
  if (expression.kind === 'price') return ['PRICE?', String(CONCEPTS[expression.thing]).toUpperCase()];
  if (expression.kind === 'presence') return ['EXISTS?', String(CONCEPTS[expression.thing]).toUpperCase()];
  if (expression.kind === 'describe') return [String(CONCEPTS[expression.thing]).toUpperCase(), expression.quality.toUpperCase()];
  if (expression.kind === 'ask_object') return ['ASK WHAT?', PREDICATES[expression.predicate].description.toUpperCase()];
  const clause = expression.kind === 'ask_when' ? expression.value : expression;
  const agent = { speaker: 'I', addressee: 'YOU', we: 'WE', other: 'HE' }[clause.event.agent];
  const predicate = PREDICATES[clause.event.predicate].description.toUpperCase();
  const argument = clause.event.argument === 'none'
    ? [] : [String(CONCEPTS[clause.event.argument]).toUpperCase()];
  const temporal = clause.time ? [clause.time.replaceAll('_', ' ').toUpperCase()] : [];

  if (code === 'de') {
    // German meaning blocks must follow the realized clause, not AST field order.
    // The finite verb comes before the subject in questions; with a modal or
    // Perfekt auxiliary, the main verb is last. Time precedes ordinary objects.
    const whenQuestion = expression.kind === 'ask_when';
    const inverted = clause.question || whenQuestion;
    const surfaceWords = example.target.trim().split(/\s+/u);
    const finite = surfaceWords[whenQuestion ? 1 : inverted ? 0 : 1]?.toLocaleLowerCase('de-DE') ?? '';
    const perfect = clause.tense === 'past' && !clause.modality &&
      /^(?:habe|haben|hat|bin|sind|ist)$/u.test(finite);
    const head = clause.modality ? [clause.modality.toUpperCase()] : perfect ? ['PAST'] : [predicate];
    const trailingVerb = clause.modality || perfect ? [predicate] : [];
    const tense = clause.tense === 'past' && !perfect ? ['PAST'] : [];
    const time = [...(clause.tense === 'future' ? ['FUTURE'] : []), ...temporal];

    // German places "kein" in the object phrase, whereas "nicht" can appear
    // after an object pronoun ("das nicht", "Ihnen nicht"). Both positions come
    // from the same word-order rules as the German sentence realizer.
    const objectFirst = ['help', 'call', 'understand'].includes(clause.event.predicate);
    const negateAfterObject = clause.negative && (objectFirst ||
      (clause.event.predicate === 'use' && clause.event.argument === 'internet'));
    const negation = clause.negative ? ['NOT'] : [];
    const middle = objectFirst
      ? [...argument, ...time, ...negation]
      : [...time, ...(negateAfterObject ? [] : negation), ...argument,
        ...(negateAfterObject ? negation : [])];
    const start = inverted ? [...head, agent] : [agent, ...head];
    return [...(whenQuestion ? ['QUESTION'] : []), ...start, ...tense,
      ...middle, ...trailingVerb, ...(clause.question && !whenQuestion ? ['QUESTION'] : [])];
  }

  // Preserve the existing presentation in French and Spanish.
  const words = [agent, predicate, ...argument];
  if (clause.tense !== 'present') words.push(clause.tense.toUpperCase());
  words.push(...temporal);
  if (clause.modality) words.push(clause.modality.toUpperCase());
  if (clause.negative) words.push('NOT');
  if (clause.question || expression.kind === 'ask_when') words.push('QUESTION');
  return words.slice(0, 7);
}

function distinctExamples(examples: readonly GeneratedExample[]): GeneratedExample[] {
  const seen = new Set<string>();
  const result: GeneratedExample[] = [];
  for (const example of examples) {
    const key = example.english.trim().toLocaleLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(example);
  }
  return result;
}

export function memoryExamples(lesson: GeneratedLesson): readonly GeneratedExample[] {
  return distinctExamples(lesson.examples).slice(0, 8);
}


/** "You" does not say whether to use Sie, vous or usted; our grammar does. */
function usesFormalYou(expression: Expression): boolean {
  switch (expression.kind) {
    case 'clause':
      return expression.event.agent === 'addressee' || expression.event.argument === 'addressee';
    case 'ask_when': return usesFormalYou(expression.value);
    case 'ask_object': return expression.agent === 'addressee';
    case 'sequence': return expression.steps.some(usesFormalYou);
    case 'link': return usesFormalYou(expression.first) || usesFormalYou(expression.second);
    default: return false;
  }
}

function simpleStatement(expression: Expression): expression is Clause {
  return expression.kind === 'clause' && !expression.question && !expression.polite;
}

/**
 * Make plausible wrong answers by changing exactly one semantic block.
 * These are realized by the same adapters as the correct answer, not by
 * swapping random translated strings from unrelated lessons.
 */
function contrasts(expression: Expression): readonly Expression[] {
  switch (expression.kind) {
    case 'clause': {
      const candidates: Expression[] = [];
      const action = expression.event;
      for (const argument of PREDICATES[action.predicate].allowedArguments) {
        if (argument === action.argument) continue;
        try {
          candidates.push({ ...expression, event: event(action.predicate, action.agent, argument, action.quantity) });
        } catch { /* The semantic frame rejects incompatible substitutions. */ }
      }
      candidates.push({ ...expression, negative: !expression.negative });
      candidates.push({ ...expression, question: !expression.question, polite: false });
      for (const agent of ['speaker', 'we', 'other', 'addressee'] as const) {
        if (agent === action.agent) continue;
        try {
          candidates.push({ ...expression, event: event(action.predicate, agent, action.argument, action.quantity) });
        } catch { /* For example, a self-directed help request is invalid. */ }
      }
      return candidates;
    }
    case 'describe': {
      const variants: Expression[] = DESCRIPTION_QUALITIES[expression.thing]
        .filter((quality) => quality !== expression.quality)
        .map((quality) => ({ ...expression, quality }));
      return [...variants,
        { ...expression, negative: !expression.negative },
        { ...expression, question: !expression.question },
        { ...expression, tense: expression.tense === 'past' ? 'present' : 'past' }];
    }
    case 'presence':
      return [...PRESENCE_THINGS.filter((thing) => thing !== expression.thing)
        .map((thing) => ({ ...expression, thing })),
        { ...expression, negative: !expression.negative },
        { ...expression, question: !expression.question }];
    case 'where': case 'route':
      return LOCATABLE_PLACES.filter((place) => place !== expression.place)
        .map((place) => ({ ...expression, place }));
    case 'price': {
      const things: readonly PricedThing[] = ['ticket', 'coffee', 'book', 'room', 'computer', 'bag', 'apartment'];
      return things.filter((thing) => thing !== expression.thing)
        .map((thing) => ({ ...expression, thing }));
    }
    case 'ask_object':
      return [...OBJECT_QUESTION_PREDICATES
        .filter((predicate) => predicate !== expression.predicate)
        .map((predicate) => ({ ...expression, predicate })),
        { ...expression, agent: expression.agent === 'speaker' ? 'addressee' : 'speaker' }];
    case 'ask_when':
      return contrasts(expression.value).filter(simpleStatement)
        .map((value) => ({ ...expression, value }));
    case 'sequence': {
      const first = expression.steps[0];
      if (!first) return [];
      return contrasts(first).filter(simpleStatement)
        .map((replacement) => ({ ...expression, steps: [replacement, ...expression.steps.slice(1)] }));
    }
    case 'link':
      return contrasts(expression.second).filter(simpleStatement)
        .map((second) => ({ ...expression, second }));
  }
}

/** Prefer other curriculum examples using the same predicate, subject and syntax. */
function proximity(a: GeneratedExample, b: GeneratedExample): number {
  if (a.source.kind === 'convention' || b.source.kind === 'convention') {
    return a.source.kind === 'convention' && b.source.kind === 'convention' ? 50 : 0;
  }
  const left = a.source.expression;
  const right = b.source.expression;
  let score = left.kind === right.kind ? 50 : 0;
  if (left.kind === 'clause' && right.kind === 'clause') {
    if (left.event.predicate === right.event.predicate) score += 50;
    if (left.event.agent === right.event.agent) score += 20;
    if (left.question === right.question) score += 10;
    if (left.event.argument === right.event.argument) score += 8;
    if (left.negative === right.negative) score += 5;
    if (left.tense === right.tense) score += 5;
  }
  return score;
}

function meaningKey(value: string): string {
  return value.trim().toLocaleLowerCase().replace(/[.!?]+$/u, '');
}

export function drillQuestions(guide: GeneratedGuide, lesson: GeneratedLesson): readonly DrillQuestion[] {
  const code = guide.language.code;
  const candidates = distinctExamples([
    ...generatePractice(lesson, code, 8), ...lesson.examples,
  ]).slice(0, 8);
  const currentIndex = guide.lessons.findIndex((entry) => entry.id === lesson.id);
  const all = distinctExamples([
    ...lesson.examples,
    ...generatePractice(lesson, code, 8),
    ...guide.lessons.slice(0, currentIndex + 1).flatMap((entry) => entry.examples),
  ]);

  return candidates.map((example, index) => {
    const selected = new Set([example.target]);
    const selectedMeanings = new Set([meaningKey(example.english)]);
    const distractors: { target: string; english: string }[] = [];

    function add(target: string, english: string): void {
      if (distractors.length === 3 || selected.has(target) || selectedMeanings.has(meaningKey(english))) return;
      selected.add(target);
      selectedMeanings.add(meaningKey(english));
      distractors.push({ target, english });
    }

    if (example.source.kind === 'expression') {
      for (const alternative of contrasts(example.source.expression)) {
        try { add(linearize(alternative, code), realizeEnglish(alternative)); }
        catch { /* Skip any unsupported semantic combination. */ }
      }
    }
    if (distractors.length < 3) {
      const nearby = all.map((candidate, rank) => ({ candidate, rank }))
        .sort((a, b) => proximity(example, b.candidate) - proximity(example, a.candidate) || a.rank - b.rank);
      for (const { candidate } of nearby) add(candidate.target, candidate.english);
    }
    // All lessons have sufficient vocabulary; fail loudly rather than silently
    // rendering a four-key quiz with missing or duplicate answer choices.
    if (distractors.length !== 3) throw new Error('Insufficient distinct drill choices for ' + lesson.id + ':' + example.id);
    const options = [...distractors];
    options.splice((index * 3 + currentIndex + 1) % 4, 0, { target: example.target, english: example.english });
    const expression = example.source.kind === 'expression' ? example.source.expression : null;
    return {
      id: lesson.id + ':' + example.id,
      english: example.english,
      target: example.target,
      options: options.map((option) => option.target),
      optionMeanings: options.map((option) => option.english),
      contextHint: expression && usesFormalYou(expression)
        ? { de: 'Formal you · Sie', fr: 'Formal you · vous', es: 'Formal you · usted' }[code] : null,
      patternHint: code === 'de' && expression?.kind === 'clause' &&
        expression.question && expression.event.agent === 'addressee'
        ? 'In German yes/no questions, the conjugated verb comes before the subject.' : null,
      example,
    };
  });
}
